function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
function text(str,x,y,size,color,align='left'){ctx.font=`900 ${size}px ui-monospace,monospace`;ctx.textAlign=align;ctx.fillStyle=color;ctx.fillText(str,x,y);}
function drawWorld(){
 ctx.setTransform(scaleX,0,0,scaleY,0,0);ctx.fillStyle='#19282a';ctx.fillRect(0,0,W,H);
 // exterior and floor plate
 rect(40,64,1200,615,'#263b38');rect(FLOOR.x,FLOOR.y,FLOOR.w,FLOOR.h,'#65755b');rect(FLOOR.x+3,FLOOR.y+3,FLOOR.w-6,FLOOR.h-6,'#768260');
 // subtle worn floor tiles
 for(let y=FLOOR.y+12;y<FLOOR.y+FLOOR.h;y+=46){for(let x=FLOOR.x+10;x<FLOOR.x+FLOOR.w;x+=52){rect(x,y,49,1,'rgba(39,58,50,.17)');rect(x,y,1,43,'rgba(39,58,50,.12)');}}
 // room rug patches
 rect(102,106,308,178,'rgba(197,171,109,.12)');rect(448,103,351,177,'rgba(114,136,104,.19)');rect(839,103,359,180,'rgba(171,132,88,.12)');rect(449,485,349,155,'rgba(175,144,85,.12)');
 // window top/bottom bright escape markers
 [[205,91],[603,91],[1002,91],[598,653],[1000,653]].forEach(([x,y])=>{rect(x,y-3,58,8,'#a8c8bc');rect(x+5,y-1,48,3,'#e1ddaa');});
 // Exterior wall
 rect(40,65,1200,26,'#344442');rect(40,653,1200,26,'#344442');rect(40,91,26,562,'#344442');rect(1214,91,26,562,'#344442');
 // center door exit marker
 drawExit(exit.x,exit.y);drawEntry(door.x,door.y);
 // walls and doors
 walls.forEach((b,i)=>{rect(b.x,b.y,b.w,b.h,'#354644');rect(b.x-2,b.y,3,b.h,'#8e9878');rect(b.x+b.w-1,b.y,3,b.h,'#1b2b2c');});
 // accessible doorway floor thresholds
 [[425,291,13,65],[425,471,13,55],[812,216,13,62],[812,460,13,56],[548,291,72,13],[602,470,70,13]].forEach(b=>{rect(...b,'#b49a62');rect(b[0],b[1]+4,b[2],4,'#dac07d');});
 furniture.forEach(drawFurniture);
 // objective labels on floor
 text('UNIT 01',93,122,10,'rgba(243,230,182,.42)');text('UNIT 02',455,122,10,'rgba(243,230,182,.42)');text('UNIT 03',837,122,10,'rgba(243,230,182,.42)');text('STAIR / EXIT',1074,431,9,'rgba(243,230,182,.62)');
 fires.forEach(drawFire);enemies.forEach(drawEnemy);civilians.forEach(drawCivilian);powerups.forEach(drawPowerup);if(carry)drawCivilian({x:player.x+12,y:player.y+13,kind:carry.kind,panic:0},true);
 drawPlayer();drawParticles();drawSpray();drawHeatOverlay();
}
function drawFurniture(b){let c=b.c;if(b.kind==='sofa'){rect(b.x,b.y+5,b.w,b.h-5,'#344e43');rect(b.x+5,b.y,b.w-10,b.h-7,'#68806a');rect(b.x+10,b.y+7,b.w-20,b.h-12,'#82916d');rect(b.x+5,b.y+b.h-5,10,7,'#503e2d');rect(b.x+b.w-15,b.y+b.h-5,10,7,'#503e2d');}else if(b.kind==='desk'){rect(b.x,b.y+5,b.w,b.h-7,'#684d36');rect(b.x+4,b.y,b.w-8,b.h-8,'#a17a4f');rect(b.x+12,b.y+8,b.w-24,5,'#c29b62');rect(b.x+9,b.y+b.h-4,9,7,'#4e3a2a');rect(b.x+b.w-18,b.y+b.h-4,9,7,'#4e3a2a');}else{rect(b.x,b.y+5,b.w,b.h-8,c);rect(b.x+5,b.y,b.w-10,b.h-10,'#a17f55');rect(b.x+8,b.y+8,b.w-16,b.h-19,'#cfb37a');}}
function drawExit(x,y){rect(x-25,y-31,50,62,'#34413b');rect(x-20,y-28,40,56,'#9b7950');rect(x-15,y-24,29,48,'#465c4d');rect(x-10,y-20,20,40,'#283c3a');rect(x+8,y-2,3,5,'#efd178');rect(x-31,y-38,62,7,'#e4d28d');text('EXIT',x,y+54,9,'#f5e29b','center');}
function drawEntry(x,y){rect(x-24,y-31,48,62,'#394a43');rect(x-17,y-25,34,50,'#182a2b');rect(x-12,y-20,24,40,'#293c37');rect(x-4,y-15,8,30,'#a48b56');text('ENTRY',x,y+49,8,'#d7c892','center');}
function drawFire(f){if(!f.alive)return;let col=COLORS[f.type],p=Math.sin(f.phase*7)*3;ctx.globalAlpha=.16;ctx.fillStyle=col;ctx.beginPath();ctx.arc(f.x,f.y,f.r+23+p,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 // jagged living-fire body and colored core
 const n=8;ctx.beginPath();for(let i=0;i<n;i++){let a=i*Math.PI*2/n,rr=f.r*(.79+Math.sin(f.phase*5+i*2)*.14)+(i%2?7:-3);let x=f.x+Math.cos(a)*rr,y=f.y+Math.sin(a)*rr; i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();ctx.fillStyle=col;ctx.fill();
 ctx.beginPath();ctx.ellipse(f.x+2,f.y+4,f.r*.53,f.r*.65,0,0,Math.PI*2);ctx.fillStyle= f.type==='WATER'?'#ffed87':f.type==='FOAM'?'#2a2923':f.type==='CRYO'?'#e4ffff':'#603288';ctx.fill();
 if(f.type==='CO2'){ctx.globalAlpha=.55;for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(f.x+Math.sin(f.phase*2+i)*16,f.y-15-i*7,8+i*2,0,Math.PI*2);ctx.fillStyle=i%2?'#8fe06a':col;ctx.fill();}ctx.globalAlpha=1;}
 if(f.type==='CRYO'){for(let i=0;i<4;i++){rect(f.x-2+Math.cos(f.phase+i)*f.r*.5,f.y-2+Math.sin(f.phase+i)*f.r*.5,4,4,'#efffff');}}
 ctx.fillStyle='#152322';ctx.font='900 8px ui-monospace';ctx.textAlign='center';ctx.fillText(f.type==='CO2'?'GAS':f.type,f.x,f.y+f.r+14);
}
function drawEnemy(e){if(!e.alive)return;const x=e.x,y=e.y,t=e.type,col=COLORS[t];ctx.globalAlpha=.2;ctx.fillStyle=col;ctx.beginPath();ctx.ellipse(x,y+15,20,7,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 if(t==='WATER'){ // orange fire creature
   ctx.fillStyle='#f97829';ctx.beginPath();ctx.moveTo(x-16,y+11);ctx.lineTo(x-18,y-5);ctx.lineTo(x-9,y-1);ctx.lineTo(x-4,y-19);ctx.lineTo(x+2,y-8);ctx.lineTo(x+10,y-17);ctx.lineTo(x+12,y-3);ctx.lineTo(x+18,y+3);ctx.lineTo(x+12,y+12);ctx.closePath();ctx.fill();rect(x-8,y-3,5,4,'#fff09a');rect(x+4,y-3,5,4,'#fff09a');rect(x-5,y+5,10,3,'#812f25');
 }else if(t==='FOAM'){ctx.fillStyle='#252721';ctx.beginPath();ctx.ellipse(x,y,17,14,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#554e39';ctx.fillRect(x-13,y-8,25,11);ctx.fillStyle='#f4a44b';ctx.fillRect(x-7,y-3,4,4);ctx.fillRect(x+4,y-3,4,4);ctx.fillStyle='#db6b35';ctx.fillRect(x-4,y+6,9,3);ctx.fillStyle='#b8aa73';ctx.fillRect(x-16,y+11,8,4);ctx.fillRect(x+8,y+11,8,4);
 }else if(t==='CRYO'){ctx.fillStyle='#85d9f1';ctx.beginPath();ctx.moveTo(x,y-18);ctx.lineTo(x+15,y-7);ctx.lineTo(x+12,y+9);ctx.lineTo(x,y+17);ctx.lineTo(x-14,y+8);ctx.lineTo(x-15,y-8);ctx.closePath();ctx.fill();ctx.fillStyle='#e7ffff';ctx.fillRect(x-8,y-5,5,5);ctx.fillRect(x+4,y-5,5,5);ctx.fillRect(x-5,y+6,10,3);rect(x-18,y-17,5,5,'#c2f5ff');rect(x+13,y+12,5,5,'#c2f5ff');
 }else{ctx.globalAlpha=.72;ctx.fillStyle='#9d57cb';ctx.beginPath();ctx.arc(x-7,y,11,0,Math.PI*2);ctx.arc(x+5,y-5,12,0,Math.PI*2);ctx.arc(x+9,y+7,10,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;rect(x-7,y-3,4,4,'#b9ff79');rect(x+5,y-4,4,4,'#b9ff79');rect(x-3,y+5,8,3,'#342345');}
 text(t==='CO2'?'CO₂':t,x,y+29,8,col,'center');}
function drawCivilian(c,carried=false){if(!c||c.saved)return;let x=c.x,y=c.y;const panic=Math.sin(c.panic||0)*2;ctx.fillStyle='rgba(16,28,25,.35)';ctx.fillRect(x-10,y+11,20,5);const colors={resident:'#d8bd8b',medic:'#b8ded0',child:'#e5b778',engineer:'#adc2a3'};rect(x-7,y-4+panic,14,14,colors[c.kind]||'#d8bd8b');rect(x-6,y-12+panic,12,10,c.kind==='child'?'#b87842':'#bd8a61');rect(x-7,y-14+panic,14,5,'#574439');rect(x-4,y-5+panic,2,2,'#303a32');rect(x+3,y-5+panic,2,2,'#303a32');rect(x-9,y+8,6,6,'#4b5650');rect(x+3,y+8,6,6,'#4b5650');if(c.kind==='medic'){rect(x-2,y-2,4,7,'#f0e9ce');rect(x-4,y,8,3,'#df6151');}if(!carried){ctx.fillStyle='rgba(255,230,161,.65)';ctx.beginPath();ctx.arc(x,y-20,3,0,Math.PI*2);ctx.fill();}}
function drawPlayer(){let x=player.x,y=player.y,blink=player.invuln>0&&Math.floor(performance.now()/90)%2===0;if(blink)ctx.globalAlpha=.5;ctx.fillStyle='rgba(15,26,24,.4)';ctx.fillRect(x-13,y+11,27,6);
 // boots, yellow suit, backpack
 rect(x-10,y+7,8,8,'#333b31');rect(x+2,y+7,8,8,'#333b31');rect(x-13,y-8,26,20,player.invuln>0?'#f05a50':'#e9b63d');rect(x-10,y-4,20,4,'#f5d762');rect(x-4,y-8,8,20,'#d5962f');rect(x-16,y-5,5,13,'#c58e2e');rect(x+11,y-5,5,13,'#c58e2e');rect(x-10,y-17,20,11,'#d79b6a');rect(x-12,y-21,24,7,'#c63835');rect(x-15,y-17,30,4,'#f25945');rect(x-6,y-14,3,2,'#202d2a');rect(x+4,y-14,3,2,'#202d2a');
 // nozzle along aim without rotating body
 let nx=x+aim.x*19,ny=y-1+aim.y*19;rect(nx-3,ny-3,7,7,'#354848');rect(nx+aim.x*4-2,ny+aim.y*4-2,5,5,'#d2d7b8');ctx.globalAlpha=1;
}
function drawPowerup(p){ctx.fillStyle=p.type==='heal'?'#e36e58':'#68c4d0';ctx.fillRect(p.x-11,p.y-11,22,22);ctx.fillStyle='#fff0c1';ctx.fillRect(p.x-3,p.y-8,6,16);ctx.fillRect(p.x-8,p.y-3,16,6);}
function drawParticles(){for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,p.size,p.size);}ctx.globalAlpha=1;}
function drawSpray(){if(!spraying||cooldown>0)return;const d=extDef[selected],color=COLORS[selected];ctx.save();ctx.globalAlpha=.32;ctx.strokeStyle=color;ctx.lineWidth=21;ctx.lineCap='square';ctx.beginPath();ctx.moveTo(player.x+aim.x*17,player.y+aim.y*17);ctx.lineTo(player.x+aim.x*d.range,player.y+aim.y*d.range);ctx.stroke();ctx.globalAlpha=.92;ctx.strokeStyle=selected==='WATER'?'#fff5b4':selected==='CRYO'?'#efffff':selected==='FOAM'?'#dbedb0':'#d7f0a2';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(player.x+aim.x*16,player.y+aim.y*16);ctx.lineTo(player.x+aim.x*d.range*.82,player.y+aim.y*d.range*.82);ctx.stroke();ctx.restore();}
function drawHeatOverlay(){if(heat>45){ctx.fillStyle=`rgba(255,73,28,${(heat-45)/500})`;ctx.fillRect(0,0,W,H);}}
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);drawWorld();requestAnimationFrame(frame);}

